  const auto now = std::chrono::steady_clock::now();
  const auto fail = [&](const std::string & say, const std::string & log) {
      node_->log("WARN", "색 탐색: " + log);
      node_->say(say);
      search_.reset();
    };
  std::string names;
  for (const auto & c : S.colors) {names += (names.empty() ? "" : ", ") + objectKo(c, "cube");}
